FString PCGUtils::InspectDependencies(const FString& AssetPath)
{
 if(!IsInGameThread() || AssetPath.IsEmpty() || AssetPath.Len()>1024 || AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(AssetPath) || !FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get().GetAssetByObjectPath(FSoftObjectPath(AssetPath)).IsValid()) throw std::runtime_error("Registered bounded PCG graph required");
 const auto* Interface=LoadObject<UPCGGraphInterface>(nullptr,*AssetPath); if(!IsValid(Interface) || Interface->HasAnyFlags(RF_Transient)) throw std::runtime_error("Persistent graph/interface required"); FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),AssetPath); J->WriteArrayStart(TEXT("references")); int32 Records=0,NodeCount=0,Cycles=0,Invalid=0; bool Truncated=false; TSet<const UPCGGraphInterface*> Visiting,Visited;
 auto Record=[&](const UPCGGraphInterface* From,const UPCGGraphInterface* To,const UPCGNode* Node,const TCHAR* Kind,const TCHAR* State) { if(Records++>=512) { Truncated=true; return; } J->WriteObjectStart(); J->WriteValue(TEXT("from"),GetPathNameSafe(From)); J->WriteValue(TEXT("to"),GetPathNameSafe(To)); J->WriteValue(TEXT("node"),GetPathNameSafe(Node)); J->WriteValue(TEXT("kind"),Kind); J->WriteValue(TEXT("state"),State); J->WriteObjectEnd(); };
 TFunction<void(const UPCGGraphInterface*,int32)> Visit; Visit=[&](const UPCGGraphInterface* Value,int32 Depth) { if(!IsValid(Value)) { ++Invalid; return; } if(Visited.Contains(Value)) return; if(Depth>32 || Visited.Num()+Visiting.Num()>=128) { Truncated=true; return; } Visiting.Add(Value);
 auto Edge=[&](const UPCGGraphInterface* Target,const UPCGNode* Node,const TCHAR* Kind) { if(!IsValid(Target)) { ++Invalid; Record(Value,nullptr,Node,Kind,TEXT("missing")); return; } if(Visiting.Contains(Target)) { ++Cycles; Record(Value,Target,Node,Kind,TEXT("cycle")); return; } Record(Value,Target,Node,Kind,Visited.Contains(Target)?TEXT("already_visited"):TEXT("resolved")); Visit(Target,Depth+1); };
 if(const auto* Instance=Cast<UPCGGraphInstance>(Value)) { const auto* Field=FindFProperty<FObjectPropertyBase>(Instance->GetClass(),TEXT("Graph")); if(Field) Edge(Cast<UPCGGraphInterface>(Field->GetObjectPropertyValue_InContainer(Instance)),nullptr,TEXT("parent")); else { ++Invalid; Record(Value,nullptr,nullptr,TEXT("parent"),TEXT("property_unavailable")); } }
 else if(const auto* Graph=Cast<UPCGGraph>(Value)) { if(Graph->GetNodes().Num()>256) Truncated=true; for(int32 I=0;I<FMath::Min(Graph->GetNodes().Num(),256);++I) { if(++NodeCount>4096) { Truncated=true; break; } const auto* Node=Graph->GetNodes()[I]; if(!IsValid(Node) || !IsValid(Node->GetSettings())) { ++Invalid; continue; } if(const auto* Settings=Cast<UPCGBaseSubgraphSettings>(Node->GetSettings())) { const auto* Original=Settings->GetOriginalSubgraphInterface(); const auto* Effective=Settings->GetSubgraphInterface(); Edge(Original,Node,TEXT("authored_subgraph")); if(Effective!=Original) Edge(Effective,Node,TEXT("effective_subgraph")); } } } else { ++Invalid; Record(Value,nullptr,nullptr,TEXT("interface"),TEXT("custom_unsupported")); }
 Visiting.Remove(Value); Visited.Add(Value); }; Visit(Interface,0); J->WriteArrayEnd(); J->WriteValue(TEXT("reference_count"),Records); J->WriteValue(TEXT("interface_count"),Visited.Num()); J->WriteValue(TEXT("nodes_examined"),FMath::Min(NodeCount,4096)); J->WriteValue(TEXT("cycle_count"),Cycles); J->WriteValue(TEXT("invalid_reference_count"),Invalid); J->WriteValue(TEXT("truncated"),Truncated); J->WriteValue(TEXT("scope"),TEXT("Current authored base-subgraph and instance-parent references only, bounded traversal. Virtual subgraph getters/native work uncapped; dynamic runtime data-driven references not proven. No compile, generation or mutation.")); J->WriteObjectEnd(); J->Close(); return Result;
}

